(function(){
const root=document.querySelector('#account-page-content');if(!root)return;
const sessionKey='almeida-customer-session';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=cents=>(Number(cents||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const dateValue=value=>value?new Date(value).toLocaleDateString('pt-BR'):'—';
const session=()=>{try{return JSON.parse(localStorage.getItem(sessionKey)||'null')}catch{return null}};
const headers=token=>({apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+token,'Content-Type':'application/json'});
async function loadEntries(){const current=session();if(!current?.access_token)return[];const response=await fetch(ALMEIDA_SUPABASE_URL+'/rest/v1/wallet_entries?select=entry_type,amount_cents,created_at,order_id,orders(public_number,amount_paid_cents,amount_due_cents)&order=created_at.desc',{headers:headers(current.access_token)});if(!response.ok)throw Error('Não foi possível carregar o saldo da carteira.');return response.json()}
function summary(entries){return entries.reduce((result,entry)=>{const cents=Math.max(0,Number(entry.amount_cents)||0);if(entry.entry_type==='credit')result.available+=cents;else if(entry.entry_type==='debit'||entry.entry_type==='reserve')result.available-=cents;return result},{available:0})}
function entryTitle(entry){return entry.entry_type==='credit'?'Cashback recebido':entry.entry_type==='debit'?'Cashback utilizado':entry.entry_type==='reserve'?'Cashback reservado':'Cashback liberado'}
function entrySign(entry){return entry.entry_type==='credit'||entry.entry_type==='release'?'+':'-'}
function entryHistory(entries){if(!entries.length)return'<p class="muted">Nenhum lançamento de cashback ainda.</p>';return entries.map(entry=>{const order=entry.orders||{},purchase=Number((order.amount_paid_cents??order.amount_due_cents)||0);return`<article class="wallet-entry"><div><strong>${entryTitle(entry)}</strong>${order.public_number?`<small>Pedido #${esc(order.public_number)}${entry.entry_type==='credit'&&purchase?` · Compra de ${money(purchase)}`:''}</small>`:''}<small>${dateValue(entry.created_at)}</small></div><b class="wallet-entry-amount ${entrySign(entry)==='+'?'positive':'negative'}">${entrySign(entry)}${money(entry.amount_cents)}</b></article>`}).join('')}
async function attach(){const nav=root.querySelector('.account-dashboard-cards'),panels=root.querySelector('.account-panels');if(!nav||!panels)return;let button=nav.querySelector('[data-account-target="#carteira"]');if(!button){button=document.createElement('button');button.type='button';button.className='account-dashboard-card';button.dataset.accountTarget='#carteira';button.innerHTML='<span class="account-tile-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M3 7.5A2.5 2.5 0 0 1 5.5 5H19a2 2 0 0 1 2 2v2h-5.5a3 3 0 0 0 0 6H21v2a2 2 0 0 1-2 2H5.5A2.5 2.5 0 0 1 3 16.5z"/><path d="M3 8h18v7h-5.5a3 3 0 0 1 0-6H21"/><circle cx="16.5" cy="12.5" r=".7"/></svg></span><span>Carteira</span>';nav.appendChild(button)}let panel=root.querySelector('#carteira');if(!panel){panel=document.createElement('section');panel.id='carteira';panel.className='account-card account-panel account-wallet';panel.hidden=true;panel.innerHTML='<div class="account-card-heading"><div><small>BENEFÍCIOS DA SUA CONTA</small><h2>Carteira</h2></div></div><p class="wallet-loading">Carregando saldo...</p>';panels.appendChild(panel)}if(!nav.dataset.walletBound){nav.dataset.walletBound='true';nav.addEventListener('click',event=>{const clicked=event.target.closest('[data-account-target]');if(!clicked)return;setTimeout(()=>{const id=clicked.dataset.accountTarget.replace(/^#/,'');root.querySelectorAll('.account-panel').forEach(item=>{item.hidden=item.id!==id});nav.querySelectorAll('[data-account-target]').forEach(item=>item.classList.toggle('active',item===clicked));if(location.hash!==`#${id}`)history.replaceState(null,'',`${location.pathname}${location.search}#${id}`)},0)})}if(panel.dataset.loaded)return;panel.dataset.loaded='true';try{const entries=await loadEntries(),balance=summary(entries);panel.innerHTML=`<div class="account-card-heading"><div><small>BENEFÍCIOS DA SUA CONTA</small><h2>Carteira</h2></div></div><div class="wallet-balance-label">Saldo cashback disponível</div><strong class="wallet-balance">${money(Math.max(0,balance.available))}</strong><p class="muted">O cashback é creditado após a confirmação da venda.</p><div class="wallet-history"><h3>Histórico de cashback</h3>${entryHistory(entries)}</div>`}catch(error){panel.innerHTML=`<div class="account-card-heading"><div><small>BENEFÍCIOS DA SUA CONTA</small><h2>Carteira</h2></div></div><p class="account-feedback error">${esc(error.message)}</p>`}const id=location.hash.replace(/^#/,'');if(id==='carteira'){root.querySelectorAll('.account-panel').forEach(item=>{item.hidden=item.id!=='carteira'});button.classList.add('active')}}
const observer=new MutationObserver(attach);observer.observe(root,{childList:true,subtree:true});attach();
})();

